<script>
  import { getEntry } from '../../../actions/sync.svelte.js'
  import DisclosureTrigger from '../Disclosure/DisclosureTrigger.svelte'
  import ModalTrigger from '../Modal/ModalTrigger.svelte'
  import PopoverTrigger from '../Popover/PopoverTrigger.svelte'

  let { show = $bindable(false), target, ...p } = $props()
  const sync = $derived(getEntry(target))
  const type = $derived(sync?.type)
</script>

{#if type === 'modal'}
  <ModalTrigger {...p} {show} {target} />
{:else if type === 'popover'}
  <PopoverTrigger {...p} {show} {target} />
{:else if type === 'disclosure'}
  <DisclosureTrigger {...p} {show} {target} />
{/if}
